### ⚠️ High-Severity Issues

#### 3. **No Security Headers** (OWASP: A05:2021 - Security Misconfiguration)
Missing security headers makes the app vulnerable to XSS, clickjacking, and other attacks.

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet());

// Or with custom configuration:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));
```

---

#### 4. **No Rate Limiting** (OWASP: A04:2021 - Insecure Design)
Vulnerable to DoS attacks and brute force.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter for auth endpoints
  skipSuccessfulRequests: true
});

app.use(generalLimiter);
// Apply stricter limiter to sensitive routes
app.use('/auth/login', authLimiter);
```

---

#### 5. **No Authentication/Authorization**
All endpoints are publicly accessible. There's no access control.

**Recommendation:**
```javascript
// middleware/auth.js
const jwt = require('jsonwebtoken');

const requireAuth = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

module.exports = { requireAuth, requireRole };
```

